shop/coupons.py.new:
"""Return the discount for ``coupon`` on ``subtotal``, or raise CouponError."""
if not coupon.code.strip():
    raise CouponError("coupon code is empty")
if coupon.percent <= 0 or coupon.percent > 100:
    raise CouponError("coupon percent out of range")
if subtotal < coupon.min_subtotal:
    raise CouponError("coupon minimum not met")
return round_cents(subtotal * coupon.percent / Decimal("100"))

"""Raise CouponError when ``coupon`` has expired."""
if coupon.expires_in_days is not None and days_since_issue > coupon.expires_in_days:
    raise CouponError("coupon expired")

shop/refunds.py.new:
"""Return the refund for ``returned_total`` after a restocking fee, or raise RefundError."""
if returned_total < 0 or returned_total > order_total:
    raise RefundError("returned total out of range")
if restocking_percent < 0 or restocking_percent > 100:
    raise RefundError("restocking percent out of range")
fee = round_cents(returned_total * restocking_percent / Decimal("100"))
return round_cents(returned_total - fee)

"""Return ``amount`` capped at ``cap``, or raise RefundError."""
if amount < 0:
    raise RefundError("refund amount is negative")
if cap < 0:
    raise RefundError("refund cap is negative")
return min(amount, cap)

